const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format((c||0)/100);
export async function studioAPI(path,data){const r=await fetch('/api/studio/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Could not complete the operation.');return v;}
export function priceHTML(q){return `<div><span>Subtotal</span><span>${money(q.subtotal)}</span></div>${q.discount?`<div><span>Discount</span><span>−${money(q.discount)}</span></div>`:''}<div><span>HST / tax</span><span>${money(q.tax)}</span></div><div class="total"><span>Estimated total</span><span>${money(q.total)}</span></div><div><span>Proposed deposit</span><span>${money(q.deposit)}</span></div><div><span>Balance</span><span>${money(q.balance)}</span></div>`;}
